function [fitresult, gof,h] = createFitFFF(cur_t_fitt, m_neg_fitt)
%CREATEFIT1(CUR_T_FITT,M_NEG_FITT)
%  Create a fit.
%
%  Data for 'untitled fit 1' fit:
%      X Input : cur_t_fitt
%      Y Output: m_neg_fitt
%  Output:
%      fitresult : a fit object representing the fit.
%      gof : structure with goodness-of fit info.
%
%  See also FIT, CFIT, SFIT.

%  Auto-generated by MATLAB on 29-Oct-2017 17:53:28


%% Fit: 'untitled fit 1'.
[xData, yData] = prepareCurveData( cur_t_fitt, m_neg_fitt );

% Set up fittype and options.
ft = fittype( 'a*exp(b*x)', 'independent', 'x', 'dependent', 'y' );
opts = fitoptions( 'Method', 'NonlinearLeastSquares' );
opts.Display = 'Off';
% opts.StartPoint = [0.996134716626885 0.0781755287531837 0.442678269775446];

% Fit model to data.
[fitresult, gof] = fit( xData, yData, ft, opts );

% Plot fit with data.

hold on
h = plot( fitresult, xData, yData);
legend( h, 'm_neg_fitt vs. cur_t_fitt', 'untitled fit 1', 'Location', 'NorthEast' );
% Label axes
xlabel cur_t_fitt
ylabel m_neg_fitt
grid on


